function medianeDeuxTries(a, b) {
    if (a.length === 0) return medianOfSingleArray(b);
    if (b.length === 0) return medianOfSingleArray(a);

    const m = a.length;
    const n = b.length;

    // Always make sure that a is the smaller array
    if (m > n) {
        [a, b] = [b, a];
        m = a.length;
        n = b.length;
    }

    let low = 0;
    let high = m - 1;
    const totalLength = m + n;

    while (low <= high) {
        const i = Math.floor((low + high) / 2);
        const j = Math.floor(totalLength / 2) - i;

        if (i < m && j >= 0 && j < n) {
            if (a[i] > b[j]) {
                high = i - 1;
            } else if (b[j] > a[i]) {
                low = i + 1;
            }
        } else if (j >= n) {
            high = i - 1;
        } else if (i < 0) {
            low = i + 1;
        }
    }

    const candidates = [];
    if (low > 0 && low <= m) candidates.push(a[low - 1]);
    if (j >= 0 && j < n) candidates.push(b[j]);

    if (totalLength % 2 === 1) {
        return Math.max(...candidates);
    } else {
        const leftMax = candidates.reduce((acc, val) => Math.max(acc, val), -Infinity);
        const rightMin = Math.min(a[low], b[j + 1]);
        return (leftMax + rightMin) / 2;
    }
}

function medianOfSingleArray(arr) {
    const len = arr.length;
    if (len % 2 === 1) {
        return arr[Math.floor(len / 2)];
    } else {
        return (arr[len/2 - 1] + arr[len/2]) / 2;
    }
}
