function optimisation_extreme(arr, target) {
    const seen = new Set();
    for (const num of arr) {
        const complement = target - num;
        if (seen.has(complement)) {
            return true;
        }
        seen.add(num);
    }
    return false;
}

function fusionnerIntervalles(tab) {
    if (tab.length === 0) return [];
    tab.sort((a, b) => a[0] - b[0]);
    const result = [tab[0]];
    for (const interval of tab.slice(1)) {
        const last = result[result.length - 1];
        if (interval[0] <= last[1]) {
            result[result.length - 1] = [last[0], Math.max(last[1], interval[1])];
        } else {
            result.push(interval);
        }
    }
    return result;
}

function prefixeCommun(tab) {
    if (tab.length === 0) return '';
    const first = tab[0];
    for (let i = 0; i < first.length; i++) {
        const char = first[i];
        for (const str of tab.slice(1)) {
            if (str[i] !== char) {
                return first.substring(0, i);
            }
        }
    }
    return first;
}

